    @Test func vectorResizingFromUInt8() {
        let mismatches = Mismatches("portVectorResizingU8ToU32InVectorCode")
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0x35E1_F36F_21C6_9425)
        for a in aInputs {
            let port = { () -> SIMD<UInt32> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<UInt32>.self, capacity: 1) { result in
                    unsafe portVectorResizingU8ToU32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<UInt32> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<UInt32>.self, capacity: 1) { result in
                    unsafe highwayVectorResizingU8ToU32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

